INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422593, 16128, 'The Guardian', 'en', 'How the Iran war unfolded: every attack and oil price change', 'https://www.theguardian.com/world/ng-interactive/2026/aug/28/how-the-iran-war-unfolded-every-attack-and-oil-price-change-visualised', 'From the first US and Israeli strikes six months ago to the battle for Hormuz, this timeline plots how Trump’s war on Iran quickly became a regional conflict with global economic consequences On 28 February 2026, the US and Israel began large-scale strikes on Iran. Tehran responded by attacking Israeli and US allies across the Gulf. Iran’s supreme leader, Ali Khamenei, was killed on the first day of strikes, and the strait of Hormuz – a crucial waterway for transporting oil – was effectively closed soon after. The conflict quickly became a regional war with global economic consequences. Donald', 'https://i.guim.co.uk/img/media/04149781ee24b1c215c6d514d486c12c9fb4037e/0_0_1350_1080/master/1350.jpg?width=140&quality=85&auto=format&fit=max&s=74cd25465572faa2f22d5a43b0632a3c', '2026-08-28T06:00:50+00:00', '2026-08-28T12:49:07.343214'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
