INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (424210, 16128, 'The Independent', 'en', 'Disaster of Trump’s war in Iran laid bare six months on: Thousands dead, economic chaos and a region in flames', 'https://www.independent.co.uk/news/world/middle-east/iran-war-trump-anniversary-deaths-economy-b3039363.html', 'The US president has been sucked into a quagmire of his own making, with both sides refusing to budge on red lines in negotiations. James C. Reynolds looks at the numbers behind a conflict that may prove to be Trump’s greatest miscalculation', 'https://static.independent.co.uk/2026/08/09/09/2289510388..?width=1200&auto=webp&trim=0%2C0%2C1%2C0', '2026-08-28T10:52:00+00:00', '2026-08-28T12:51:37.771268'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
