INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (424282, 16128, 'Le Monde', 'en', 'War in Iran: ''Every day, the world reminds Europeans that they lack the ability to influence decisions made in the US''', 'https://www.lemonde.fr/en/opinion/article/2026/08/28/war-in-iran-every-day-the-world-reminds-europeans-that-they-lack-the-ability-to-influence-decisions-made-in-the-us_6756922_23.html', 'In 2015, European diplomacy played a central role in negotiations over Iran''s nuclear program. Six months after the conflict triggered by the US and Israel, Europe has been sidelined from the talks. Political scientist Pierre Ramond revisits the specific context of the 2015 agreement.', 'https://img.lemde.fr/2015/07/14/150/0/5232/2616/644/322/60/0/78fee63_150454097b14420ea0f8febf7f92f4ca-150454097b14420ea0f8febf7f92f4ca-0.jpg', '2026-08-28T01:55:52+00:00', '2026-08-28T12:51:44.470492'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
