INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425241, 16128, 'South China Morning Post', 'en', 'Iran’s supreme leader remains unseen 6 months after war began', 'https://www.scmp.com/news/world/middle-east/article/3365550/irans-supreme-leader-remains-unseen-6-months-after-war-began', 'Six months after the air strikes that began the war and propelled ⁠a badly wounded Mojtaba Khamenei into the role of Iran’s supreme leader, he remains entirely unseen and unheard by Iranians – a vacuum at the heart of his country’s leadership. Questions over his condition and role are growing increasingly fraught, with Iran facing critical decisions over a war that has set the Middle East aflame while trashing the country’s already fragile economy. Iranian officials and other senior sources in...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/ca702792-c674-4772-858d-e522281cc25c_19d4d57c.jpg?itok=zsvu0wI3&v=1787895815', '2026-08-28T05:43:39+00:00', '2026-08-28T12:53:51.884882'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
