INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427192, 16137, 'Associated Press', 'en', 'Fed Chair Warsh signals rate hikes may be needed with US inflation stubbornly elevated', 'https://news.google.com/rss/articles/CBMiqgFBVV95cUxNTUFJSHBlaThPY3QxNm1TZEpORnhMam5QQUZTc203emxiY0pKSWJLYWtvaFZNMUd0UGluNzJHVHNhcTZERkpOdmpQR2ZsWC10Q1IxMTFIaDVVRkQ3WjhFWFZsX254RVVJUG9QemZ6ZEtIbndJZk1iYUtuNDEzUGFmejVPZTZlQXl5SEx5WGZPSzh1WHlXalY1dldNR2l3a0RkT0t2M1RZTEdLZw?oc=5', 'Fed Chair Warsh signals rate hikes may be needed with US inflation stubbornly elevated AP News', '', '2026-08-28T18:27:00+00:00', '2026-08-29T00:03:05.461909'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427245, 16137, 'BBC News', 'en', 'Fed has ''work to do'' if price rises don''t ease for Americans, Warsh says', 'https://www.bbc.co.uk/news/articles/cy9zjgv9lgdo', 'Kevin Warsh remarks suggest interest rates could be increased if policymakers think inflation is running too high.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/5899/live/39824e70-a2fe-11f1-80b3-bf1a174ac193.jpg', '2026-08-28T15:15:26+00:00', '2026-08-29T00:03:12.419434'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427268, 16137, 'The Guardian', 'en', 'Fed chair says delivering ‘stable prices’ is central bank’s job as inflation persists', 'https://www.theguardian.com/business/2026/aug/28/kevin-warsh-federal-reserve-inflation', 'However, Kevin Warsh didn’t say if interest rates would change in coming months, as inflation remains stubborn The US Federal Reserve is not done fighting high inflation, its chair, Kevin Warsh, said in his first major speech in the role on Friday, emphasizing that it was “the Fed’s job to deliver stable prices”. Warsh did not indicate where the Fed will take interest rates in the coming months, despite US inflation remaining stubbornly above the central bank’s 2% target amid the war in Iran. But his speech was taken by markets as a signal that rates may rise in the coming months, a move that ', 'https://i.guim.co.uk/img/media/1af8fe39a9ff21d1976e753bf02d26f64d0354b0/1779_1033_4046_3238/master/4046.jpg?width=140&quality=85&auto=format&fit=max&s=509ad875000eec5562259a9dc26ea61e', '2026-08-28T15:48:57+00:00', '2026-08-29T00:03:22.219453'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427301, 16137, 'Al Jazeera English', 'en', 'US Fed chair warns inflation progress insufficient, hints at rate hikes', 'https://www.aljazeera.com/economy/2026/8/28/us-fed-chair-warns-inflation-progress-insufficient-hints-at-rate-hikes?traffic_source=rss', 'Kevin Warsh in speech underscores Fed''s commitment to tackling inflation, with rate hikes possibly on horizon.', '', '2026-08-28T17:22:01+00:00', '2026-08-29T00:03:26.848242'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427872, 16137, 'The Economic Times', 'en', 'US stocks today: US stocks end lower as Warsh keeps inflation fight front and centre', 'https://economictimes.indiatimes.com/markets/us-stocks/wall-street-guide/us-stocks-today-us-stocks-end-lower-as-warsh-keeps-inflation-fight-front-and-centre/articleshow/133599688.cms', 'US stocks ended lower as Fed Chair Kevin Warsh reaffirmed the central bank’s focus on bringing inflation to 2%, raising expectations for a possible September rate hike. The Dow, S&P 500 and Nasdaq fell, while Nvidia and other tech stocks weakened. Investors also assessed mixed corporate earnings and economic data.', 'https://img.etimg.com/photo/msid-133599688,imgsize-130504.cms', '2026-08-28T20:15:56+00:00', '2026-08-29T00:04:38.787040'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427876, 16137, 'The Economic Times', 'en', 'Jackson Hole: Will Kevin Warsh''s inflation warning put Nifty under pressure on Monday?', 'https://economictimes.indiatimes.com/markets/stocks/news/jackson-hole-will-kevin-warshs-inflation-warning-put-nifty-under-pressure-on-monday/articleshow/133595035.cms', 'Nifty faces potential pressure on Monday following US Fed Chairman Kevin Warsh''s hawkish inflation comments at Jackson Hole. Elevated US bond yields, a stronger dollar, and rising crude oil prices threaten foreign institutional flows, while technical analysts highlight 24,200 as a key resistance level for the Indian stock market.', 'https://img.etimg.com/photo/msid-133595035,imgsize-74838.cms', '2026-08-28T15:41:32+00:00', '2026-08-29T00:04:38.897068'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427882, 16137, 'The Economic Times', 'en', 'US Treasury yields rise after comments from Fed''s Kevin Warsh at Jackson Hole', 'https://economictimes.indiatimes.com/markets/us-stocks/news/us-treasury-yields-rise-after-comments-from-feds-kevin-warsh-at-jackson-hole/articleshow/133593960.cms', 'U.S. Treasury yields saw an increase during trading sessions. Federal Reserve Chairman Kevin Warsh indicated further action may be necessary. Policymakers need confidence that inflation is returning to the target.', 'https://img.etimg.com/photo/msid-133593960,imgsize-55694.cms', '2026-08-28T14:33:32+00:00', '2026-08-29T00:04:39.014530'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427883, 16137, 'The Economic Times', 'en', 'US Fed chairman Kevin Warsh says inflation is elevated and ''concerning'' at Jackson Hole', 'https://economictimes.indiatimes.com/markets/us-stocks/wall-street-guide/us-fed-chairman-kevin-warsh-says-inflation-is-elevated-and-concerning-at-jackson-hole/articleshow/133593773.cms', 'US Federal Reserve Chairman Kevin Warsh said on Friday that high inflation in the world''s largest economy was "concerning," as he opened a key central bankers'' meeting in Jackson Hole, Wyoming. Warsh, who has been reticent to share his views on the economy since he took office, said that the central bank''s "predominant focus right now should be on prices."', 'https://img.etimg.com/photo/msid-133593773,imgsize-81444.cms', '2026-08-28T14:18:26+00:00', '2026-08-29T00:04:39.035211'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427885, 16137, 'The Economic Times', 'en', 'US stocks today: US stocks edge higher as Warsh keeps inflation focus in spotlight', 'https://economictimes.indiatimes.com/markets/us-stocks/wall-street-guide/us-stocks-today-us-stocks-open-subdued-ahead-of-warshs-speech/articleshow/133592641.cms', 'Wall Street edged higher as Fed Chair Kevin Warsh kept inflation and the central bank''s 2% target in focus, prompting traders to raise bets on a September rate hike. Chip stocks retreated after Nvidia''s AI-fueled rally, while PayPal tumbled and Gap surged following company-specific developments.', 'https://img.etimg.com/photo/msid-133592641,imgsize-197968.cms', '2026-08-28T13:39:41+00:00', '2026-08-29T00:04:39.081451'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
