INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (428491, 16137, 'NPR', 'en', 'Fed''s Kevin Warsh warns inflation is too high, sparking bets rate hikes are coming', 'https://www.npr.org/2026/08/28/nx-s1-5947903/federal-reserve-inflation-jackson-hole-interest-rates', 'Fed Chair Kevin Warsh reiterated his commitment to fighting inflation in a major speech — raising expectations that rate hikes may be coming, though he did not clearly spell out a path going forward.', 'https://npr.brightspotcdn.com/dims3/default/strip/false/crop/7249x4835+0+0/resize/7249x4835!/?url=http%3A%2F%2Fnpr-brightspot.s3.amazonaws.com%2F16%2F38%2F543982a349d4bb76c5c993d3a03a%2Fgettyimages-2291773172.jpg', '2026-08-28T16:05:40+00:00', '2026-08-29T00:06:18.232196'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
